const calcApasxolhseisNoticeOptions=()=>({target:document.querySelector("main.payroll-form-layout")||document.body,heightAuto:!1,width:"min(560px, 100%)",confirmButtonText:"Κλείσιμο",showCancelButton:!1,customClass:{title:"custom-title",popup:"custom-swal-popup new-year-confirmation z-depth-5",container:"new-year-confirmation-container calc-apasxolhseis-notice",confirmButton:"class-info custom-confirm-button custom-swal-button"}});document.getElementById("calcApasxolhseonButton")?.addEventListener("click",async()=>{const t=document.getElementById("apo_hmeromhnia")?.value,e=document.getElementById("eos_hmeromhnia")?.value,o=document.getElementById("ypokatasthmata_stathera")?.value||"",a=document.getElementById("xronosProetoimasias_stathera")?.value||"",s=document.getElementById("proorhApoxorhsh_stathera")?.value||"";try{const n=await fetch("/ergazomenoi/programmata/calcApasxolhseisPeriodoy",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({apo_hmeromhnia:t,eos_hmeromhnia:e,ypokatasthmata_stathera:o,proorh_proseleysh:a,proorhApoxorhsh_stathera:s})}),c=await n.json();if(!c.success)return Swal.fire({...calcApasxolhseisNoticeOptions(),icon:"warning",title:"Υπολογισμός Απασχολήσεων",text:c.message||"Ο υπολογισμός δεν ολοκληρώθηκε."});console.log(c),await Swal.fire({...calcApasxolhseisNoticeOptions(),icon:"success",title:"Υπολογισμός Απασχολήσεων",text:`Βρέθηκαν ${c.employeesCount} εργαζόμενοι.`})}catch(t){console.error(t),await Swal.fire({...calcApasxolhseisNoticeOptions(),icon:"error",title:"Υπολογισμός Απασχολήσεων",text:"Σφάλμα επικοινωνίας με τον server."})}});